def parse_pairs(s):
    pairs = {}
    key = ''
    value = ''
    in_quotes = False
    quote_char = ''
    for c in s + ';':
        if in_quotes:
            if c == quote_char:
                in_quotes = False
                value += c
                pairs[key] = value.strip()
            else:
                value += c
        else:
            if c == '=':
                key = value.strip()
                value = ''
            elif c == "'":
                in_quotes = True
                quote_char = c
            elif c == ';':
                if key:
                    pairs[key] = value.strip()
                    key = ''
                    value = ''
            else:
                value += c
    return pairs
