class VFS:
    def mkdir(self, path):
        names = path.strip('/').split('/')
        current = self.root
        for name in names:
            if name not in current.children:
                current.children[name] = Dir(name)
            current = current.children[name]
        if current.children:
            raise KeyError

    def write(self, path, content):
        names = path.strip('/').split('/')
        current = self.root
        for name in names[:-1]:
            if name not in current.children:
                current.children[name] = Dir(name)
            current = current.children[name]
        if names[-1] in current.children:
            if isinstance(current.children[names[-1]], Dir):
                raise KeyError
            current.children[names[-1]].content = content
        else:
            current.children[names[-1]] = File(names[-1], content)
    def read(self, path):
        names = path.strip('/').split('/')
        current = self.root
        for name in names:
            if name in current.children:
                current = current.children[name]
            else:
                raise KeyError
        if isinstance(current, File):
            return current.content
        else:
            raise KeyError

    def ls(self, path=""):
        names = path.strip('/').split('/')
        current = self.root
        for name in names:
            if name in current.children:
                current = current.children[name]
            else:
                raise KeyError
        return sorted([child.name for child in current.children.values()])

    def rm(self, path):
        names = path.strip('/').split('/')
        current = self.root
        parent = None
        for i, name in enumerate(names):
            if name in current.children:
                child = current.children[name]
                if i == len(names) - 1:
                    if isinstance(child, Dir):
                        self._rm_dir(child)
                    else:
                        del current.children[name]
                    return
                else:
                    parent = current
                    current = child
            else:
                raise KeyError

    def _rm_dir(self, dir):
        for name in dir.children:
            if isinstance(dir.children[name], Dir):
                self._rm_dir(dir.children[name])
            else:
                del dir.children[name]
        del dir.children
